import pandas as pd
import numpy as np


def run(inputs: dict) -> dict:
    cp = inputs["customer_profile"].copy()
    pc = inputs["profile_changes"].copy()

    NULL_SENTINEL = "<<NULL>>"

    def apply_email(old, val):
        # val is the raw change value (may be NaN/None)
        if pd.isna(val):
            return old
        if val == NULL_SENTINEL:
            return None
        return val.strip().lower()

    def apply_plain(old, val):
        if pd.isna(val):
            return old
        if val == NULL_SENTINEL:
            return None
        return val

    def eq_nullsafe(a, b):
        if a is None and b is None:
            return True
        if a is None or b is None:
            return False
        return a == b

    # Build initial profile state keyed by customer_id
    profiles = {}
    for _, row in cp.iterrows():
        cust_id = row["customer_id"]
        email = row["email"]
        phone = row["phone"]
        tier = row["tier"]
        updated_seq = row["updated_seq"]

        profiles[cust_id] = {
            "email": None if pd.isna(email) else email,
            "phone": None if pd.isna(phone) else phone,
            "tier": None if pd.isna(tier) else tier,
            "updated_seq": updated_seq,
        }

    # Sort changes by change_seq (unique, so no tie-break needed)
    pc_sorted = pc.sort_values("change_seq", kind="mergesort")

    # Group changes by customer_id, preserving change_seq order
    changes_by_cust = {}
    for _, row in pc_sorted.iterrows():
        cust_id = row["customer_id"]
        changes_by_cust.setdefault(cust_id, []).append(row)

    for cust_id, changes in changes_by_cust.items():
        existing = profiles.get(cust_id)

        if existing is not None:
            applicable = [c for c in changes if c["change_seq"] > existing["updated_seq"]]
        else:
            applicable = changes

        for change in applicable:
            if existing is None:
                # Create new row from this change
                new_email = apply_email(None, change["email"])
                new_phone = apply_plain(None, change["phone"])
                new_tier = apply_plain(None, change["tier"])
                existing = {
                    "email": new_email,
                    "phone": new_phone,
                    "tier": new_tier,
                    "updated_seq": change["change_seq"],
                }
            else:
                old_email = existing["email"]
                old_phone = existing["phone"]
                old_tier = existing["tier"]

                new_email = apply_email(old_email, change["email"])
                new_phone = apply_plain(old_phone, change["phone"])
                new_tier = apply_plain(old_tier, change["tier"])

                if (
                    eq_nullsafe(new_email, old_email)
                    and eq_nullsafe(new_phone, old_phone)
                    and eq_nullsafe(new_tier, old_tier)
                ):
                    # No-op: do not advance updated_seq, fields unchanged
                    pass
                else:
                    existing["email"] = new_email
                    existing["phone"] = new_phone
                    existing["tier"] = new_tier
                    existing["updated_seq"] = change["change_seq"]

        profiles[cust_id] = existing

    rows = []
    for cust_id, prof in profiles.items():
        rows.append(
            {
                "customer_id": cust_id,
                "email": prof["email"],
                "phone": prof["phone"],
                "tier": prof["tier"],
                "updated_seq": prof["updated_seq"],
            }
        )

    result = pd.DataFrame(
        rows, columns=["customer_id", "email", "phone", "tier", "updated_seq"]
    )

    if not result.empty:
        result["customer_id"] = result["customer_id"].astype("int64")
        result["updated_seq"] = result["updated_seq"].astype("int64")

    return {"new_profile": result}
